import{_ as t,o as s,c as a,ak as i}from"./chunks/framework.sV-XtlWr.js";const k=JSON.parse('{"title":"Getting started","description":"Piwi Dashboard is a self-hosted server plus a Playwright reporter that keeps every test run. Run the dashboard, connect your suite with one command, and open your first run in three steps.","frontmatter":{"title":"Getting started","description":"Piwi Dashboard is a self-hosted server plus a Playwright reporter that keeps every test run. Run the dashboard, connect your suite with one command, and open your first run in three steps.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/getting-started.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/getting-started.html"}],["meta",{"property":"og:title","content":"Getting started | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi Dashboard is a self-hosted server plus a Playwright reporter that keeps every test run. Run the dashboard, connect your suite with one command, and open your first run in three steps."}]]},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1790803547000}'),n={name:"guide/getting-started.md"};function r(h,e,o,p,d,l){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Piwi is a <strong>server plus a Playwright reporter</strong>. The reporter runs inside <code>npx playwright test</code> and sends the results to the server, which keeps every run with its traces and renders the dashboard. Three steps set up both. New to the vocabulary (<em>run</em>, <em>test case</em>, <em>execution</em>, <em>cluster</em>)? <a href="./concepts.html">Core concepts</a> defines each term the dashboard uses.</p><h2 id="_1-run-the-dashboard" tabindex="-1">1. Run the dashboard <a class="header-anchor" href="#_1-run-the-dashboard" aria-label="Permalink to &quot;1. Run the dashboard&quot;">​</a></h2><p>The dashboard is one Node process. Pick the way to run it that fits:</p><table tabindex="0"><thead><tr><th>Path</th><th>Best for</th><th>Needs</th></tr></thead><tbody><tr><td><a href="/features/desktop.html">Desktop app</a></td><td>One developer running Playwright locally</td><td>Nothing; the runtime is bundled. Windows x64, Apple-silicon macOS and Linux x86-64; the installers are not signed yet</td></tr><tr><td>Docker <em>(below)</em></td><td>A shared instance for a team, or anything long-lived</td><td>Docker; about 300 MB RAM, 1 vCPU, <code>linux/amd64</code> or <code>linux/arm64</code></td></tr><tr><td><a href="/operate/deployment.html#npm-npx-quick-local-run"><code>npx @piwitests/server</code></a></td><td>A quick local run</td><td>Node.js 22 or later</td></tr><tr><td><a href="/operate/deployment.html#one-click-deploy">One-click deploy</a></td><td>A shared instance with no server of your own</td><td>An account on the host</td></tr></tbody></table><p>With Docker:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-dy78e" id="tab-EkFmvU1" checked><label data-title="Linux / macOS" for="tab-EkFmvU1">Linux / macOS</label><input type="radio" name="group-dy78e" id="tab-ipAkt47"><label data-title="Windows (PowerShell)" for="tab-ipAkt47">Windows (PowerShell)</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenx/piwitests-server:latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1001:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # the container runs as non-root UID 1001</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.data:/app/.data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenx/piwitests-server:latest</span></span></code></pre></div><div class="language-ps1 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ps1</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker pull phenx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">piwitests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server:latest</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v \${PWD}</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.data:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.data phenx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">piwitests</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server:latest</span></span></code></pre></div></div></div><p>The dashboard answers at <code>http://localhost:3000</code>. On Linux hosts the container runs as the non-root UID 1001, which is why the snippet creates <code>.data</code> with the right owner; see <a href="/operate/deployment.html#permission-issues-with-volumes">Permission issues with volumes</a> if the container cannot write to it. <a href="/operate/deployment.html">Deployment</a> covers Docker Compose, PostgreSQL and Kubernetes.</p><p>With the desktop app, keep it running: a reporter with no server configured finds it by itself. Its URL and access token, for when you need them, are on its <strong>Setup</strong> page under <strong>Send results to this app</strong>.</p><p>Your test project is unaffected by these requirements: Node 22 is the dashboard&#39;s requirement, not your suite&#39;s. Want to look around first? The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> runs in your browser on seeded data.</p><h2 id="_2-connect-your-suite" tabindex="-1">2. Connect your suite <a class="header-anchor" href="#_2-connect-your-suite" aria-label="Permalink to &quot;2. Connect your suite&quot;">​</a></h2><h3 id="fast-path-one-command" tabindex="-1">Fast path: one command <a class="header-anchor" href="#fast-path-one-command" aria-label="Permalink to &quot;Fast path: one command&quot;">​</a></h3><p>From your Playwright project, one command installs the reporter, wraps your <code>playwright.config</code>, creates the <a href="./capture-fixtures.html">capture fixtures</a> file and records the connection in <code>.env.example</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre></div><p>Every step is idempotent, so it is safe to re-run. When <code>init</code> finds a config shape it will not rewrite, or a fixtures file that already exists, it reports that step as <code>manual</code> with the exact change to make instead of touching the file. Pass <code>--dry-run</code> to preview, or <code>--json</code> for a machine-readable plan that a coding agent can follow to finish the manual steps. <code>init</code> also adds the <a href="/features/agent-skills.html">Piwi agent skills</a> to the project. See <code>npx @piwitests/reporter init --help</code> for all options.</p><blockquote><p>The package is <code>@piwitests/reporter</code> and its command is <code>piwi</code>. Invoke it through the package name, <code>npx @piwitests/reporter &lt;command&gt;</code>, so npx resolves this package: <code>npx piwi</code> would fetch an unrelated <code>piwi</code> package from npm. Once the reporter is a dependency of your project, <code>npx piwi &lt;command&gt;</code> works too.</p></blockquote><p>If authentication is on, pass an <a href="/operate/api-keys.html">API key</a> as <code>PIWI_API_KEY</code>. To wire the reporter in by hand, or to send one run without editing your config, see <a href="./reporter.html">Reporter</a>.</p><h2 id="_3-run-your-tests" tabindex="-1">3. Run your tests <a class="header-anchor" href="#_3-run-your-tests" aria-label="Permalink to &quot;3. Run your tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The run streams into the dashboard while it executes, and the reporter prints a <code>View run:</code> link at the end. Open it.</p><p>In CI nothing Piwi-specific is needed: the same reporter runs inside <code>npx playwright test</code>, pointed at your instance with <code>PIWI_DASHBOARD_URL</code> and <code>PIWI_API_KEY</code>. <a href="./ci.html">CI &amp; sharding</a> has the pipeline examples.</p><h2 id="your-first-failure" tabindex="-1">Your first failure <a class="header-anchor" href="#your-first-failure" aria-label="Permalink to &quot;Your first failure&quot;">​</a></h2><p>When a test fails, its execution page opens on what happened, the most likely cause and the next step, with the trace, screenshots and logs underneath. <a href="./first-failure.html">Your first failure, explained</a> walks through one failing test from its headline to its evidence.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./concepts.html">Core concepts</a>: the vocabulary the dashboard and these docs use</li><li><a href="./reporter.html">Reporter</a>: manual setup, options, streaming and authentication</li><li><a href="./capture-fixtures.html">Capture fixtures</a>: what the fixtures file adds</li><li><a href="/operate/capabilities.html">Choose what you use</a>: turn off the capabilities you do not need</li><li><a href="/operate/deployment.html">Deployment</a>: running the dashboard for a team</li></ul>`,25)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
